```java
@Service
public class UomConverterService {
    private static final MathContext MC = MathContext.DECIMAL128;
    private static final int RESULT_SCALE = 10;

    public BigDecimal convert(BigDecimal value, UomUnit from, UomUnit to) {
        return convert(value, from, to, null);
    }

    public BigDecimal convert(BigDecimal value, UomUnit from, UomUnit to, BigDecimal densityGramsPerMl) {
        if (value == null) throw new UomException("value must not be null");
        if (from == null || to == null) throw new UomException("units must not be null");

        if (from == to) return value;

        if (from.getCategory() == to.getCategory()) {
            BigDecimal baseValue = value.multiply(from.getFactorToBase(), MC);
            return baseValue.divide(to.getFactorToBase(), RESULT_SCALE, RoundingMode.HALF_UP);
        }

        // Cross-category: need density
        if (densityGramsPerMl == null) {
            throw new UomException("Cross-category conversion from " + from.getCode() + " to " + to.getCode() + " requires density (g/ml)");
        }

        // Convert to base of from, then to base of to
        BigDecimal baseValue = value.multiply(from.getFactorToBase(), MC);

        // Volume -> Weight: base is ml, need to convert to g
        // Weight -> Volume: base is g, need to convert to ml
        BigDecimal baseInTargetCategory;
        if (from.getCategory() == UomCategory.VOLUME && to.getCategory() == UomCategory.WEIGHT) {
            // ml * density(g/ml) = g
            baseInTargetCategory = baseValue.multiply(densityGramsPerMl, MC);
        } else if (from.getCategory() == UomCategory.WEIGHT && to.getCategory() == UomCategory.VOLUME) {
            // g / density(g/ml) = ml
            baseInTargetCategory = baseValue.divide(densityGramsPerMl, RESULT_SCALE, RoundingMode.HALF_UP);
        } else {
            throw new UomException("Cannot convert between " + from.getCategory() + " and " + to.getCategory());
        }

        return baseInTargetCategory.divide(to.getFactorToBase(), RESULT_SCALE, RoundingMode.HALF_UP);
    }
}
