import { Box, Paper, Typography } from '@mui/material';

/**
 * Stable axis identifiers. These MUST match between the <YAxis> element
 * and the series (<Bar>/<Line>) that should be plotted against it.
 */
const Y_AXIS_ID_REVENUE = 'revenue';
const Y_AXIS_ID_ORDERS = 'orders';

/**
 * Format a revenue value for axis ticks and tooltips.
 * @param {number|string} value
 * @returns {string}
 */
const formatRevenue = (value) => {
  if (value === null || value === undefined || value === '') return '';
  const num = Number(value);
  if (Number.isNaN(num)) return '';
  const abs = Math.abs(num);
  if (abs >= 1e9) return `$${(num / 1e9).toFixed(1)}B`;
  if (abs >= 1e6) return `$${(num / 1e6).toFixed(1)}M`;
  if (abs >= 1e3) return `$${(num / 1e3).toFixed(0)}k`;
  return `$${num}`;
};

/**
 * Format an order count for axis ticks and tooltips.
 * @param {number|string} value
 * @returns {string}
 */
const formatOrders = (value) => {
  if (value === null || value === undefined || value === '') return '';
  const num = Number(value);
  if (Number.isNaN(num)) return '';
  const abs = Math.abs(num);
  if (abs >= 1e9) return `${(num / 1e9).toFixed(1)}B`;
  if (abs >= 1e6) return `${(num / 1e6).toFixed(1)}M`;
  if (abs >= 1e3) return `${(num / 1e3).toFixed(1)}k`;
  return `${num}`;
};

/**
 * Shared tooltip formatter. Recharts invokes this once per series in the
 * hovered payload; we branch on the series' dataKey so revenue values are
 * rendered as currency and order values as plain counts.
 *
 * @param {number} value
 * @param {string} name
 * @param {{ dataKey?: string }} item
 * @returns {[string, string]}
 */
const tooltipFormatter = (value, name, item) => {
  const dataKey = item && item.dataKey;
  if (dataKey === 'revenue') {
    return [formatRevenue(value), 'Revenue'];
  }
  if (dataKey === 'orders') {
    return [formatOrders(value), 'Orders'];
  }
  return [String(value), name];
};

/**
 * RevenueOverview
 *
 * Renders a dual-axis composed chart:
 *   - Left axis  (yAxisId="revenue"): revenue bars, currency-formatted.
 *   - Right axis (yAxisId="orders"):  orders line, integer-formatted.
 *
 * Each axis computes its own domain independently, so a revenue of $500k
 * and 500 orders will both fill their respective axes without one
 * squashing the other.
 *
 * @param {Object}   props
 * @param {Array}    [props.data=[]]
 * @param {string}   [props.revenueLabel='Revenue']
 * @param {string}   [props.ordersLabel='Orders']
 * @param {string}   [props.revenueColor='#8884d8']
 * @param {string}   [props.ordersColor='#82ca9d']
 * @param {number}   [props.height=300]
 * @param {React.ReactNode} [props.title]
 */
const RevenueOverview = ({
  data = [],
  revenueLabel = 'Revenue',
  ordersLabel = 'Orders',
  revenueColor = '#8884d8',
  ordersColor = '#82ca9d',
  height = 300,
  title,
}) => {
  const safeData = Array.isArray(data) ? data : [];

  return (
    <Box sx={{ width: '100%' }}>
      <Paper
        elevation={1}
        sx={{ p: 2, display: 'flex', flexDirection: 'column' }}
      >
        {title && (
          <Typography
            variant="h6"
            component="div"
            sx={{ mb: 2, fontWeight: 600 }}
          >
            {title}
          </Typography>
        )}

        <Box
          data-testid="revenue-overview-chart"
          sx={{ width: '100%', height }}
        >
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
              data={safeData}
              margin={{ top: 10, right: 20, left: 10, bottom: 0 }}
            >
              <CartesianGrid
                strokeDasharray="3 3"
                vertical={false}
                opacity={0.3}
              />

              <XAxis
                dataKey="name"
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 12, fill: '#666' }}
                dy={10}
              />

              {/* Primary (left) axis: revenue. Independent auto-domain. */}
              <YAxis
                yAxisId={Y_AXIS_ID_REVENUE}
                orientation="left"
                tickFormatter={formatRevenue}
                tick={{ fontSize: 12, fill: revenueColor }}
                axisLine={{ stroke: revenueColor }}
                tickLine={{ stroke: revenueColor }}
                width={80}
                domain={['auto', 'auto']}
                allowDecimals={false}
              />

              {/* Secondary (right) axis: orders. Independent auto-domain. */}
              <YAxis
                yAxisId={Y_AXIS_ID_ORDERS}
                orientation="right"
                tickFormatter={formatOrders}
                tick={{ fontSize: 12, fill: ordersColor }}
                axisLine={{ stroke: ordersColor }}
                tickLine={{ stroke: ordersColor }}
                width={60}
                domain={['auto', 'auto']}
                allowDecimals={false}
              />

              <Tooltip
                shared
                formatter={tooltipFormatter}
                contentStyle={{
                  backgroundColor: '#fff',
                  border: '1px solid #e0e0e0',
                  borderRadius: '8px',
                  boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                }}
                labelFormatter={(label) => (
                  <span style={{ fontWeight: 600, color: '#333' }}>
                    {label}
                  </span>
                )}
              />

              <Legend wrapperStyle={{ paddingTop: '10px' }} />

              {/* Revenue bars — bound to the LEFT axis. */}
              <Bar
                yAxisId={Y_AXIS_ID_REVENUE}
                dataKey="revenue"
                name={revenueLabel}
                fill={revenueColor}
                radius={[4, 4, 0, 0]}
                maxBarSize={40}
              />

              {/* Orders line — bound to the RIGHT axis. */}
              <Line
                yAxisId={Y_AXIS_ID_ORDERS}
                type="monotone"
                dataKey="orders"
                name={ordersLabel}
                stroke={ordersColor}
                strokeWidth={2.5}
                dot={{
                  r: 4,
                  strokeWidth: 2,
                  stroke: ordersColor,
                  fill: '#fff',
                }}
                activeDot={{
                  r: 6,
                  stroke: ordersColor,
                  fill: '#fff',
                }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        </Box>
      </Paper>
    </Box>
  );
};

export default RevenueOverview;
```

## Why this fixes the bug

| Concern | Before | After |
|---|---|---|
| Axis binding | `<Bar>` / `<Line>` had no `yAxisId`, so Recharts defaulted both to the first axis | Each series explicitly declares `yAxisId={Y_AXIS_ID_REVENUE}` / `yAxisId={Y_AXIS_ID_ORDERS}` |
| Domain inheritance | Orders inherited revenue's `[0, 500000]` domain, flattening the line | Each `<YAxis>` has `domain={['auto', 'auto']}` — Recharts computes each independently |
| Tick units | Both axes showed raw numbers | Revenue ticks use `$…k/M/B`; orders ticks use `…k/M/B` |
| Tooltip units | Single formatter, ambiguous units | `tooltipFormatter` branches on `item.dataKey` and returns `[formatted, 'Revenue' \| 'Orders']` |
| Legend labels | Generic | Uses `revenueLabel` / `ordersLabel` props (defaults `Revenue` / `Orders`) |

