          isCurrentMonth: isSameMonth(date, viewMonth),
          isToday: isToday(date),
          shifts: shifts.filter((shift) => isSameDay(new Date(shift.start), date)),
        });
      }
      result.push(week);
      cursor = addDays(cursor, 7);
    }
    return result;
  }, [shifts, viewMonth]);
