    private final ApplicationEventPublisher publisher;
    private final boolean allowNegativeStock;

    @Transactional(propagation = MANDATORY) // must be in sale tx
    public void deductAll(List<IngredientRequirement> reqs, String reference) {
        // sort by rawMaterialId to avoid deadlocks
        for each: deduct(...)
    }

    private void deduct(IngredientRequirement req, String reference) {
        RawMaterial rm = repo.findByIdForUpdate(req.rawMaterialId()).orElseThrow();
        BigDecimal before = rm.getCurrentStock();
        BigDecimal after = before.subtract(req.quantity());
        if (after.signum() < 0 && !allowNegativeStock) throw new InsufficientStockException(...);
        rm.setCurrentStock(after);
        repo.save(rm);
        if (after.compareTo(rm.getReorderLevel()) <= 0) {
            publisher.publishEvent(new LowStockEvent(this, rm.getId(), rm.getName(), rm.getCode(), after, rm.getReorderLevel(), rm.getBaseUom(), reference));
        }
    }
}
