package com.sims.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

@Service
@Slf4j
public class UomConverterService {

    public enum Dimension {
        VOLUME, WEIGHT, COUNT, UNKNOWN
    }

    // Volume conversion rates to base unit: Milliliters (ml)
    private static final Map<String, BigDecimal> VOLUME_TO_ML = new HashMap<>();
    // Weight conversion rates to base unit: Grams (g)
    private static final Map<String, BigDecimal> WEIGHT_TO_G = new HashMap<>();
    // Count conversion rates to base unit: Unit / Each (1)
    private static final Map<String, BigDecimal> COUNT_TO_UNIT = new HashMap<>();

    static {
        // Volume
        VOLUME_TO_ML.put("ML", BigDecimal.valueOf(1.0));
        VOLUME_TO_ML.put("MILLILITER", BigDecimal.valueOf(1.0));
        VOLUME_TO_ML.put("L", BigDecimal.valueOf(1000.0));
        VOLUME_TO_ML.put("LITER", BigDecimal.valueOf(1000.0));
        VOLUME_TO_ML.put("LITRE", BigDecimal.valueOf(1000.0));
        VOLUME_TO_ML.put("FL_OZ", BigDecimal.valueOf(29.5735));
        VOLUME_TO_ML.put("FLOZ", BigDecimal.valueOf(29.5735));
        VOLUME_TO_ML.put("FL OZ", BigDecimal.valueOf(29.5735));
        VOLUME_TO_ML.put("FLUID_OUNCE", BigDecimal.valueOf(29.5735));
        VOLUME_TO_ML.put("CUP", BigDecimal.valueOf(236.588));
        VOLUME_TO_ML.put("PINT", BigDecimal.valueOf(473.176));
        VOLUME_TO_ML.put("PT", BigDecimal.valueOf(473.176));
        VOLUME_TO_ML.put("QUART", BigDecimal.valueOf(946.353));
        VOLUME_TO_ML.put("QT", BigDecimal.valueOf(946.353));
        VOLUME_TO_ML.put("GAL", BigDecimal.valueOf(3785.41));
        VOLUME_TO_ML.put("GALLON", BigDecimal.valueOf(3785.41));
        VOLUME_TO_ML.put("TBSP", BigDecimal.valueOf(14.7868));
        VOLUME_TO_ML.put("TABLESPOON", BigDecimal.valueOf(14.7868));
        VOLUME_TO_ML.put("TSP", BigDecimal.valueOf(4.92892));
        VOLUME_TO_ML.put("TEASPOON", BigDecimal.valueOf(4.92892));
        VOLUME_TO_ML.put("BUCKET_10L", BigDecimal.valueOf(10000.0));
        VOLUME_TO_ML.put("10L_BUCKET", BigDecimal.valueOf(10000.0));
        VOLUME_TO_ML.put("10L BUCKET", BigDecimal.valueOf(10000.0));

        // Weight
        WEIGHT_TO_G.put("G", BigDecimal.valueOf(1.0));
        WEIGHT_TO_G.put("GRAM", BigDecimal.valueOf(1.0));
        WEIGHT_TO_G.put("KG", BigDecimal.valueOf(1000.0));
        WEIGHT_TO_G.put("KILOGRAM", BigDecimal.valueOf(1000.0));
        WEIGHT_TO_G.put("OZ", BigDecimal.valueOf(28.3495));
        WEIGHT_TO_G.put("OUNCE", BigDecimal.valueOf(28.3495));
        WEIGHT_TO_G.put("LB", BigDecimal.valueOf(453.592));
        WEIGHT_TO_G.put("LBS", BigDecimal.valueOf(453.592));
        WEIGHT_TO_G.put("POUND", BigDecimal.valueOf(453.592));
        WEIGHT_TO_G.put("MG", BigDecimal.valueOf(0.001));
        WEIGHT_TO_G.put("MILLIGRAM", BigDecimal.valueOf(0.001));
        WEIGHT_TO_G.put("BAG_50LB", BigDecimal.valueOf(22679.6));
        WEIGHT_TO_G.put("50LB_BAG", BigDecimal.valueOf(22679.6));

        // Count / Packaging
        COUNT_TO_UNIT.put("UNIT", BigDecimal.valueOf(1.0));
        COUNT_TO_UNIT.put("PIECE", BigDecimal.valueOf(1.0));
        COUNT_TO_UNIT.put("EACH", BigDecimal.valueOf(1.0));
        COUNT_TO_UNIT.put("ITEM", BigDecimal.valueOf(1.0));
        COUNT_TO_UNIT.put("DOZEN", BigDecimal.valueOf(12.0));
        COUNT_TO_UNIT.put("CASE_24", BigDecimal.valueOf(24.0));
        COUNT_TO_UNIT.put("CASE_12", BigDecimal.valueOf(12.0));
        COUNT_TO_UNIT.put("PACK_6", BigDecimal.valueOf(6.0));
        COUNT_TO_UNIT.put("PACK_10", BigDecimal.valueOf(10.0));
        COUNT_TO_UNIT.put("PACK", BigDecimal.valueOf(1.0));
        COUNT_TO_UNIT.put("BOX", BigDecimal.valueOf(1.0));
    }

    private String normalize(String unit) {
        if (unit == null) return "UNIT";
        return unit.trim().toUpperCase().replace("-", "_").replace(".", "");
    }

    public Dimension getDimension(String unit) {
        String u = normalize(unit);
        if (VOLUME_TO_ML.containsKey(u)) return Dimension.VOLUME;
        if (WEIGHT_TO_G.containsKey(u)) return Dimension.WEIGHT;
        if (COUNT_TO_UNIT.containsKey(u)) return Dimension.COUNT;
        return Dimension.UNKNOWN;
    }

    public boolean areCompatible(String fromUnit, String toUnit) {
        Dimension d1 = getDimension(fromUnit);
        Dimension d2 = getDimension(toUnit);
        return d1 != Dimension.UNKNOWN && d1 == d2;
    }

    /**
     * Converts an amount from one unit of measure to another.
     * Supports within-dimension conversions (Volume <-> Volume, Weight <-> Weight, Count <-> Count)
     * and cross-dimension conversions when a density (g/ml) or packSize conversion factor is provided.
     */
    public BigDecimal convert(BigDecimal amount, String fromUnit, String toUnit, BigDecimal densityOrPackSize) {
        if (amount == null) return BigDecimal.ZERO;
        String from = normalize(fromUnit);
        String to = normalize(toUnit);

        if (from.equals(to)) {
            return amount;
        }

        Dimension fromDim = getDimension(from);
        Dimension toDim = getDimension(to);

        // Same Dimension: VOLUME
        if (fromDim == Dimension.VOLUME && toDim == Dimension.VOLUME) {
            BigDecimal ml = amount.multiply(VOLUME_TO_ML.get(from));
            return ml.divide(VOLUME_TO_ML.get(to), 6, RoundingMode.HALF_UP);
        }

        // Same Dimension: WEIGHT
        if (fromDim == Dimension.WEIGHT && toDim == Dimension.WEIGHT) {
            BigDecimal g = amount.multiply(WEIGHT_TO_G.get(from));
            return g.divide(WEIGHT_TO_G.get(to), 6, RoundingMode.HALF_UP);
        }

        // Same Dimension: COUNT
        if (fromDim == Dimension.COUNT && toDim == Dimension.COUNT) {
            BigDecimal units = amount.multiply(COUNT_TO_UNIT.get(from));
            return units.divide(COUNT_TO_UNIT.get(to), 6, RoundingMode.HALF_UP);
        }

        // Cross-Dimension: Volume <-> Weight using Density (default 1.0 g/ml if not specified)
        BigDecimal density = (densityOrPackSize != null && densityOrPackSize.compareTo(BigDecimal.ZERO) > 0)
                ? densityOrPackSize : BigDecimal.ONE;

        if (fromDim == Dimension.VOLUME && toDim == Dimension.WEIGHT) {
            // ml * density(g/ml) = g
            BigDecimal ml = amount.multiply(VOLUME_TO_ML.get(from));
            BigDecimal grams = ml.multiply(density);
            return grams.divide(WEIGHT_TO_G.get(to), 6, RoundingMode.HALF_UP);
        }

        if (fromDim == Dimension.WEIGHT && toDim == Dimension.VOLUME) {
            // g / density(g/ml) = ml
            BigDecimal grams = amount.multiply(WEIGHT_TO_G.get(from));
            BigDecimal ml = grams.divide(density, 6, RoundingMode.HALF_UP);
            return ml.divide(VOLUME_TO_ML.get(to), 6, RoundingMode.HALF_UP);
        }

        // Cross-Dimension with PackSize: e.g. Count (1 bucket) to Volume (10 L)
        if (densityOrPackSize != null && densityOrPackSize.compareTo(BigDecimal.ZERO) > 0) {
            if (fromDim == Dimension.COUNT) {
                // e.g. 2 buckets * 10L = 20L
                BigDecimal totalBulk = amount.multiply(densityOrPackSize);
                return totalBulk;
            } else if (toDim == Dimension.COUNT) {
                // e.g. 0.2366L / 10L = 0.02366 buckets
                return amount.divide(densityOrPackSize, 6, RoundingMode.HALF_UP);
            }
        }

        log.warn("Cannot convert incompatible units: {} -> {}. Returning original amount.", fromUnit, toUnit);
        return amount;
    }

    /**
     * Calculates the exact ingredient portion cost from bulk supplier pricing.
     * E.g. Bulk Batter: $35.00 for a 10L bucket (packSize = 10, unit = L).
     * Portion used: 8 fl oz.
     * Portion Cost = ($35.00 / 10,000 ml) * (8 * 29.5735 ml) = $0.828 ≈ $0.83.
     */
    public BigDecimal calculatePortionCost(
            BigDecimal bulkPrice,
            BigDecimal bulkQuantity,
            String bulkUnit,
            BigDecimal portionQuantity,
            String portionUnit,
            BigDecimal density
    ) {
        if (bulkPrice == null || bulkPrice.compareTo(BigDecimal.ZERO) <= 0 ||
            bulkQuantity == null || bulkQuantity.compareTo(BigDecimal.ZERO) <= 0 ||
            portionQuantity == null || portionQuantity.compareTo(BigDecimal.ZERO) <= 0) {
            return BigDecimal.ZERO;
        }

        // Convert portionQuantity in portionUnit to bulkUnit
        BigDecimal portionInBulkUnit = convert(portionQuantity, portionUnit, bulkUnit, density);
        BigDecimal costPerBulkUnit = bulkPrice.divide(bulkQuantity, 6, RoundingMode.HALF_UP);
        return portionInBulkUnit.multiply(costPerBulkUnit).setScale(4, RoundingMode.HALF_UP);
    }

    /**
     * Calculates how many bulk units are depleted by a portion.
     * E.g. 8 fl oz of batter from a 10L bucket -> 0.02366 buckets (or 0.2366 L).
     */
    public BigDecimal calculatePortionDepletion(
            BigDecimal portionQty,
            String portionUnit,
            String bulkUnit,
            BigDecimal packSize
    ) {
        if (portionQty == null || portionQty.compareTo(BigDecimal.ZERO) <= 0) {
            return BigDecimal.ZERO;
        }
        BigDecimal inBulkUnit = convert(portionQty, portionUnit, bulkUnit, packSize);
        if (packSize != null && packSize.compareTo(BigDecimal.ZERO) > 0 && !normalize(portionUnit).equals(normalize(bulkUnit))) {
            return inBulkUnit.divide(packSize, 6, RoundingMode.HALF_UP);
        }
        return inBulkUnit;
    }

    public Map<String, List<String>> getSupportedUnits() {
        Map<String, List<String>> units = new LinkedHashMap<>();
        units.put("Volume", Arrays.asList("ml", "L", "fl oz", "cup", "pint", "quart", "gal", "tbsp", "tsp", "10L bucket"));
        units.put("Weight", Arrays.asList("g", "kg", "oz", "lb", "50lb bag"));
        units.put("Count", Arrays.asList("unit", "piece", "dozen", "case_24", "case_12", "pack_6", "pack_10"));
        return units;
    }
}

