package com.sims.controller;

import com.sims.service.UomConverterService;
import lombok.Data;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/uom")
@RequiredArgsConstructor
public class UomController {

    private final UomConverterService uomConverterService;

    @GetMapping("/units")
    public ResponseEntity<Map<String, List<String>>> getSupportedUnits() {
        return ResponseEntity.ok(uomConverterService.getSupportedUnits());
    }

    @PostMapping("/convert")
    public ResponseEntity<ConversionResponse> convert(@RequestBody ConversionRequest request) {
        BigDecimal converted = uomConverterService.convert(
                request.getAmount(),
                request.getFromUnit(),
                request.getToUnit(),
                request.getDensityOrPackSize()
        );
        ConversionResponse response = new ConversionResponse();
        response.setOriginalAmount(request.getAmount());
        response.setFromUnit(request.getFromUnit());
        response.setConvertedAmount(converted);
        response.setToUnit(request.getToUnit());
        response.setCompatible(uomConverterService.areCompatible(request.getFromUnit(), request.getToUnit()));
        return ResponseEntity.ok(response);
    }

    @PostMapping("/portion-cost")
    public ResponseEntity<PortionCostResponse> calculatePortionCost(@RequestBody PortionCostRequest request) {
        BigDecimal cost = uomConverterService.calculatePortionCost(
                request.getBulkPrice(),
                request.getBulkQuantity(),
                request.getBulkUnit(),
                request.getPortionQuantity(),
                request.getPortionUnit(),
                request.getDensity()
        );
        PortionCostResponse response = new PortionCostResponse();
        response.setPortionCost(cost);
        response.setBulkPrice(request.getBulkPrice());
        response.setPortionQuantity(request.getPortionQuantity());
        response.setPortionUnit(request.getPortionUnit());
        return ResponseEntity.ok(response);
    }

    @Data
    public static class ConversionRequest {
        private BigDecimal amount;
        private String fromUnit;
        private String toUnit;
        private BigDecimal densityOrPackSize;
    }

    @Data
    public static class ConversionResponse {
        private BigDecimal originalAmount;
        private String fromUnit;
        private BigDecimal convertedAmount;
        private String toUnit;
        private boolean isCompatible;
    }

    @Data
    public static class PortionCostRequest {
        private BigDecimal bulkPrice;
        private BigDecimal bulkQuantity;
        private String bulkUnit;
        private BigDecimal portionQuantity;
        private String portionUnit;
        private BigDecimal density;
    }

    @Data
    public static class PortionCostResponse {
        private BigDecimal portionCost;
        private BigDecimal bulkPrice;
        private BigDecimal portionQuantity;
        private String portionUnit;
    }
}

