export const SUPPORTED_UNITS = [
  // Volume
  { label: 'Fluid Ounces (fl oz)', value: 'fl oz', dimension: 'volume' },
  { label: 'Milliliters (ml)', value: 'ml', dimension: 'volume' },
  { label: 'Liters (L)', value: 'L', dimension: 'volume' },
