  { label: 'Case of 12', value: 'case_12', dimension: 'count' },
  { label: 'Pack of 6', value: 'pack_6', dimension: 'count' },
];

function normalize(unit) {
  if (!unit) return 'unit';
  return String(unit).toLowerCase().trim().replace(/[-_]/g, ' ');
}

export function getDimension(unit) {
  const u = normalize(unit);
  if (VOLUME_TO_ML[u] || VOLUME_TO_ML[u.replace(/\s+/g, '_')]) return 'volume';
  if (WEIGHT_TO_G[u] || WEIGHT_TO_G[u.replace(/\s+/g, '_')]) return 'weight';
  if (COUNT_TO_UNIT[u] || COUNT_TO_UNIT[u.replace(/\s+/g, '_')]) return 'count';
  return 'unknown';
}

/**
 * Converts quantity from fromUnit to toUnit.
 * @param {number} amount
 * @param {string} fromUnit
 * @param {string} toUnit
 * @param {object} [options] { density: 1.0 (g/ml), packSize: 1.0 }
 */
export function convertUom(amount, fromUnit, toUnit, options = {}) {
  const num = parseFloat(amount);
  if (isNaN(num) || num === 0) return 0;

  const from = normalize(fromUnit);
  const to = normalize(toUnit);

  if (from === to) return num;

  const fromDim = getDimension(from);
  const toDim = getDimension(to);

  // Volume -> Volume
  if (fromDim === 'volume' && toDim === 'volume') {
    const fromRate = VOLUME_TO_ML[from] || VOLUME_TO_ML[from.replace(/\s+/g, '_')] || 1.0;
    const toRate = VOLUME_TO_ML[to] || VOLUME_TO_ML[to.replace(/\s+/g, '_')] || 1.0;
    return (num * fromRate) / toRate;
  }

  // Weight -> Weight
  if (fromDim === 'weight' && toDim === 'weight') {
    const fromRate = WEIGHT_TO_G[from] || WEIGHT_TO_G[from.replace(/\s+/g, '_')] || 1.0;
    const toRate = WEIGHT_TO_G[to] || WEIGHT_TO_G[to.replace(/\s+/g, '_')] || 1.0;
    return (num * fromRate) / toRate;
  }

  // Count -> Count
  if (fromDim === 'count' && toDim === 'count') {
    const fromRate = COUNT_TO_UNIT[from] || COUNT_TO_UNIT[from.replace(/\s+/g, '_')] || 1.0;
    const toRate = COUNT_TO_UNIT[to] || COUNT_TO_UNIT[to.replace(/\s+/g, '_')] || 1.0;
    return (num * fromRate) / toRate;
  }

  // Cross-dimension: Volume <-> Weight with density (g/ml)
  const density = options.density || 1.0;
  if (fromDim === 'volume' && toDim === 'weight') {
    const ml = num * (VOLUME_TO_ML[from] || 1.0);
    const grams = ml * density;
    const toRate = WEIGHT_TO_G[to] || 1.0;
    return grams / toRate;
  }

  if (fromDim === 'weight' && toDim === 'volume') {
    const grams = num * (WEIGHT_TO_G[from] || 1.0);
    const ml = grams / density;
    const toRate = VOLUME_TO_ML[to] || 1.0;
    return ml / toRate;
  }

  // Pack size conversion
  if (options.packSize && options.packSize > 0) {
    if (fromDim === 'count') {
      return num * options.packSize;
    }
    if (toDim === 'count') {
      return num / options.packSize;
    }
  }

  return num;
}

/**
 * Calculates ingredient portion cost from bulk purchasing price.
 * E.g. Bulk Batter: $35.00 for a 10L bucket (packSize = 10, unit = 'L').
 * Portion: 8 fl oz.
 * Return: portion cost in dollars.
 */
export function calculatePortionCost(bulkPrice, bulkPackSize, bulkUnit, portionQty, portionUnit, density = 1.0) {
  const price = parseFloat(bulkPrice) || 0;
  const packSize = parseFloat(bulkPackSize) || 1;
  const qty = parseFloat(portionQty) || 0;

  if (price <= 0 || packSize <= 0 || qty <= 0) return 0;

  // Convert portion quantity into bulk unit
  const portionInBulkUnit = convertUom(qty, portionUnit || bulkUnit, bulkUnit, { density, packSize });
  const costPerBulkUnit = price / packSize;
  const portionCost = portionInBulkUnit * costPerBulkUnit;

  return Math.round(portionCost * 10000) / 10000;
}

/**
 * Calculates total recipe food cost, food cost percentage, and gross profit margin.
 * @param {Array} ingredients Array of { quantity, unitOfMeasure, rawMaterial: { purchasePrice, packSize, unitOfMeasure } }
 * @param {number} sellingPrice Retail menu selling price
 */
export function calculateRecipeTotal(ingredients = [], sellingPrice = 0) {
  let totalCost = 0;

  ingredients.forEach((item) => {
    const rm = item.rawMaterial || {};
    const cost = calculatePortionCost(
      rm.purchasePrice,
      rm.packSize || 1,
      rm.unitOfMeasure || 'unit',
      item.quantityRequired || item.quantity,
      item.unitOfMeasure || rm.unitOfMeasure || 'unit'
    );
    totalCost += cost;
  });

  const price = parseFloat(sellingPrice) || 0;
  const foodCostPercent = price > 0 ? (totalCost / price) * 100 : 0;
  const grossProfit = Math.max(0, price - totalCost);
  const grossMarginPercent = price > 0 ? (grossProfit / price) * 100 : 0;

  return {
    totalCost: Math.round(totalCost * 100) / 100,
    sellingPrice: Math.round(price * 100) / 100,
    foodCostPercent: Math.round(foodCostPercent * 10) / 10,
    grossProfit: Math.round(grossProfit * 100) / 100,
    grossMarginPercent: Math.round(grossMarginPercent * 10) / 10,
  };
}

