#### 1. SaleService.java (Proportional BOM Depletion & LowStock Events)
```java
package com.sims.service;

import com.sims.event.SaleEvent;
import com.sims.model.BillOfMaterialItem;
import com.sims.model.Sale;
import com.sims.model.SaleItem;
import com.sims.model.Product;
import com.sims.model.Customer;
import com.sims.model.CashDrawer;
import com.sims.repository.BillOfMaterialItemRepository;
import com.sims.repository.SaleRepository;
import com.sims.repository.ProductRepository;
import com.sims.repository.CustomerRepository;
import com.sims.repository.CashDrawerRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class SaleService {

    private final SaleRepository saleRepository;
    private final ProductRepository productRepository;
    private final BillOfMaterialItemRepository bomRepository;
    private final CustomerRepository customerRepository;
    private final CashDrawerRepository cashDrawerRepository;
    private final KafkaTemplate<String, Object> kafkaTemplate;
    private final TaxEngineService taxEngineService;
    private final UomConverterService uomConverterService;

    @Transactional
    @CacheEvict(value = {"sales", "analytics"}, allEntries = true)
    public Sale createSale(Sale sale) {
        // Calculate subtotal
        BigDecimal subtotal = BigDecimal.ZERO;
        if (sale.getItems() != null) {
            for (SaleItem item : sale.getItems()) {
                if (item.getSubtotal() != null) {
                    subtotal = subtotal.add(item.getSubtotal());
                } else if (item.getUnitPrice() != null && item.getQuantity() != null) {
                    BigDecimal itemSub = item.getUnitPrice().multiply(new BigDecimal(item.getQuantity()));
                    item.setSubtotal(itemSub);
                    subtotal = subtotal.add(itemSub);
                }
            }
        }
        sale.setSubtotal(subtotal);

        // Calculate tax using Multi-Jurisdiction Tax Engine
        BigDecimal tax = taxEngineService.calculateTax(sale, sale.getRegion());
        sale.setTax(tax);

        // Calculate total
        BigDecimal total = subtotal.add(tax);
        if (sale.getDiscount() != null) {
            total = total.subtract(sale.getDiscount());
        }
        sale.setTotal(total);

        if (sale.getItems() != null) {
            sale.getItems().forEach(item -> {
                item.setSale(sale);
                Product product = productRepository.findById(item.getProduct().getId())
                        .orElseThrow(() -> new RuntimeException("Product not found"));

                // Back-of-House Automated Recipe Ingredient Deduction (BOM)
                List<BillOfMaterialItem> boms = bomRepository.findByFinishedGood(product);
                if (boms != null && !boms.isEmpty()) {
                    log.info("Processing BOM ingredient deduction for Finished Good '{}' ({} ingredients)", product.getName(), boms.size());
                    for (BillOfMaterialItem bomItem : boms) {
                        Product rawMaterial = bomItem.getRawMaterial();
                        if (rawMaterial == null) continue;

                        BigDecimal qtyRequiredPerPortion = bomItem.getQuantityRequired() != null ? bomItem.getQuantityRequired() : BigDecimal.ONE;
                        BigDecimal totalIngredientNeeded = qtyRequiredPerPortion.multiply(BigDecimal.valueOf(item.getQuantity()));
                        String recipeUom = bomItem.getUnitOfMeasure() != null ? bomItem.getUnitOfMeasure() : rawMaterial.getUnitOfMeasure();
                        String rawMaterialUom = rawMaterial.getUnitOfMeasure() != null ? rawMaterial.getUnitOfMeasure() : "unit";

                        // Convert portion requirement into raw material storage unit via UomConverterService
                        BigDecimal depletion = uomConverterService.convert(
                                totalIngredientNeeded,
                                recipeUom,
                                rawMaterialUom,
                                rawMaterial.getPackSize()
                        );

                        // Deduct from raw material packSize and stockQuantity
                        if (rawMaterial.getPackSize() != null && rawMaterial.getPackSize().compareTo(BigDecimal.ZERO) > 0) {
                            rawMaterial.setPackSize(rawMaterial.getPackSize().subtract(depletion));
                        }
                        int unitsToDeduct = Math.max(1, depletion.intValue());
                        int currentStock = rawMaterial.getStockQuantity() != null ? rawMaterial.getStockQuantity() : 0;
                        rawMaterial.setStockQuantity(Math.max(0, currentStock - unitsToDeduct));
                        productRepository.save(rawMaterial);
                        log.info("BOM Depletion: Raw Material '{}' depleted by {} {} (Stock remaining: {})",
                                rawMaterial.getName(), depletion, rawMaterialUom, rawMaterial.getStockQuantity());

                        // Emit low stock event for raw material if stock falls below reorder level
                        if (rawMaterial.getReorderLevel() != null && rawMaterial.getStockQuantity() <= rawMaterial.getReorderLevel()) {
                            com.sims.event.LowStockEvent lowStockEvent = new com.sims.event.LowStockEvent(
                                    rawMaterial.getId(),
                                    rawMaterial.getName(),
                                    rawMaterial.getSku(),
                                    rawMaterial.getStockQuantity(),
                                    rawMaterial.getReorderLevel()
                            );
                            try {
                                kafkaTemplate.send("low-stock-events", String.valueOf(rawMaterial.getId()), lowStockEvent);
                                log.warn("Published low-stock event for recipe ingredient: {}", rawMaterial.getName());
                            } catch (Exception e) {
                                log.warn("Could not publish Kafka event for {}: {}", rawMaterial.getName(), e.getMessage());
                            }
                        }
                    }
                }

                // Deduct finished good stock
                int currentFgStock = product.getStockQuantity() != null ? product.getStockQuantity() : 0;
                product.setStockQuantity(Math.max(0, currentFgStock - item.getQuantity()));
                productRepository.save(product);

                // Check for low stock on finished good
                if (product.getReorderLevel() != null && product.getStockQuantity() <= product.getReorderLevel()) {
                    com.sims.event.LowStockEvent lowStockEvent = new com.sims.event.LowStockEvent(
                            product.getId(),
                            product.getName(),
                            product.getSku(),
                            product.getStockQuantity(),
                            product.getReorderLevel()
                    );
                    try {
                        kafkaTemplate.send("low-stock-events", String.valueOf(product.getId()), lowStockEvent);
                        log.info("Published low-stock event for Product ID: {}", product.getId());
                    } catch (Exception e) {
                        log.warn("Could not publish Kafka event for {}: {}", product.getName(), e.getMessage());
                    }
                }
            });
        }

        // Handle customer points and total spent
        if (sale.getCustomer() != null && sale.getCustomer().getId() != null) {
            Customer customer = customerRepository.findById(sale.getCustomer().getId()).orElse(null);
            if (customer != null) {
                customer.setTotalSpent(customer.getTotalSpent().add(sale.getTotal()));
                int earnedPoints = sale.getTotal().divideToIntegralValue(new BigDecimal("10")).intValue();
                customer.setLoyaltyPoints((customer.getLoyaltyPoints() == null ? 0 : customer.getLoyaltyPoints()) + earnedPoints);
                customerRepository.save(customer);
                sale.setCustomer(customer);
            }
        }

        Sale savedSale = saleRepository.save(sale);
        log.info("Sale saved with ID: {}", savedSale.getId());

        // Publish event to Kafka
        SaleEvent event = new SaleEvent(
                savedSale.getId(),
                savedSale.getCustomer() != null ? savedSale.getCustomer().getId() : null,
                savedSale.getTotal(),
                savedSale.getItems() != null ? savedSale.getItems().stream().map(item -> item.getProduct().getId()).collect(Collectors.toList()) : null
        );

        try {
            kafkaTemplate.send("sales-events", String.valueOf(savedSale.getId()), event);
            log.info("Published sale-created event to Kafka for Sale ID: {}", savedSale.getId());
        } catch (Exception e) {
            log.warn("Could not publish Kafka sales event: {}", e.getMessage());
        }

        return savedSale;
    }

    @Transactional
    @CacheEvict(value = {"sales", "analytics"}, allEntries = true)
    public Sale refundSale(Long id) {
        Sale sale = saleRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Sale not found"));

        if ("REFUNDED".equals(sale.getStatus())) {
            throw new RuntimeException("Sale is already refunded");
        }

        sale.setStatus("REFUNDED");

        // Return stock
        if (sale.getItems() != null) {
            sale.getItems().forEach(item -> {
                Product product = item.getProduct();
                product.setStockQuantity(product.getStockQuantity() + item.getQuantity());
                productRepository.save(product);
            });
        }

        // Deduct points
        if (sale.getCustomer() != null && sale.getCustomer().getId() != null) {
            Customer customer = customerRepository.findById(sale.getCustomer().getId()).orElse(null);
            if (customer != null) {
                customer.setTotalSpent(customer.getTotalSpent().subtract(sale.getTotal()));
                int earnedPoints = sale.getTotal().divideToIntegralValue(new BigDecimal("10")).intValue();
                customer.setLoyaltyPoints(Math.max(0, (customer.getLoyaltyPoints() == null ? 0 : customer.getLoyaltyPoints()) - earnedPoints));
                customerRepository.save(customer);
            }
        }

        return saleRepository.save(sale);
    }

    @Cacheable(value = "sales", key = "'all'")
    public List<Sale> getAllSales() {
        return saleRepository.findAll();
    }

    @Cacheable(value = "sales", key = "#id")
    public Sale getSaleById(Long id) {
        return saleRepository.findById(id).orElseThrow(() -> new RuntimeException("Sale not found"));
    }
}

