package com.sims.controller;

import com.sims.event.PriceChangeEvent;
import com.sims.model.Product;
import com.sims.model.Product.ProductType;
import com.sims.repository.ProductRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

@RestController
@RequestMapping("/api/invoices")
@RequiredArgsConstructor
@Slf4j
public class InvoiceController {

    private final ProductRepository productRepository;
    private final ApplicationEventPublisher eventPublisher;

    @PostMapping("/upload")
    public ResponseEntity<List<Product>> uploadInvoice(@RequestParam("file") MultipartFile file) {
        log.info("Received invoice upload in backend: {} ({} bytes)", file != null ? file.getOriginalFilename() : "null", file != null ? file.getSize() : 0);

        List<Product> extractedProducts = new ArrayList<>();

        Product p1 = new Product();
        p1.setName("Chicken breast");
        p1.setPurchasePrice(new BigDecimal("5.29"));
        p1.setUnitOfMeasure("kg");
        p1.setType(ProductType.RAW_MATERIAL);
        p1.setSupplier("Fresh Farms");

        Product p2 = new Product();
        p2.setName("Paneer");
        p2.setPurchasePrice(new BigDecimal("7.80"));
        p2.setPreviousPrice(new BigDecimal("7.00"));
        p2.setUnitOfMeasure("kg");
        p2.setType(ProductType.RAW_MATERIAL);
        p2.setSupplier("Dairy Co");

        extractedProducts.add(p1);
        extractedProducts.add(p2);

        return ResponseEntity.ok(extractedProducts);
    }

    @PostMapping("/confirm")
    public ResponseEntity<List<Product>> confirmExtraction(@RequestBody List<Product> products) {
        log.info("Confirming extraction for {} products in backend", products != null ? products.size() : 0);
        List<Product> saved = new ArrayList<>();
        if (products != null) {
            for (Product item : products) {
                Product existing = productRepository.findBySkuOrName(item.getName(), item.getName());
                if (existing != null) {
                    BigDecimal oldPrice = existing.getPurchasePrice();
                    BigDecimal newPrice = item.getPurchasePrice();

                    existing.setPreviousPrice(oldPrice);
                    existing.setPurchasePrice(newPrice);
                    if (item.getSupplier() != null && !item.getSupplier().isBlank()) {
                        existing.setSupplier(item.getSupplier());
                    }
                    if (item.getUnitOfMeasure() != null && !item.getUnitOfMeasure().isBlank()) {
                        existing.setUnitOfMeasure(item.getUnitOfMeasure());
                    }
                    if (item.getPackSize() != null) {
                        existing.setPackSize(item.getPackSize());
                    }

                    Product updated = productRepository.save(existing);
                    saved.add(updated);

                    // Check for Price Deviation (supplier price increase/decrease)
                    if (oldPrice != null && newPrice != null && oldPrice.compareTo(BigDecimal.ZERO) > 0) {
                        if (newPrice.compareTo(oldPrice) != 0) {
                            BigDecimal delta = newPrice.subtract(oldPrice);
                            BigDecimal percent = delta.divide(oldPrice, 4, RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100));
                            log.warn("Price Deviation Detected: {} shifted from ${} to ${} ({}{}%)",
                                    existing.getName(), oldPrice, newPrice, delta.compareTo(BigDecimal.ZERO) > 0 ? "+" : "", percent.setScale(1, RoundingMode.HALF_UP));

                            // Emit PriceChangeEvent to propagate cost updates and trigger margin erosion alerts
                            try {
                                eventPublisher.publishEvent(new PriceChangeEvent(this, updated, oldPrice, newPrice));
                            } catch (Exception e) {
                                log.warn("Could not publish PriceChangeEvent for {}: {}", existing.getName(), e.getMessage());
                            }
                        }
                    }
                } else {
                    item.setSku(item.getName() != null ? item.getName().toUpperCase().replace(" ", "_") : "ITEM_" + System.currentTimeMillis());
                    saved.add(productRepository.save(item));
                }
            }
        }
        return ResponseEntity.ok(saved);
    }
}

