#### 2. CostPropagationListener.java (Recipe Margin Erosion & AI Insights)
```java
package com.sims.service;

import com.sims.event.PriceChangeEvent;
import com.sims.model.AiInsight;
import com.sims.model.BillOfMaterialItem;
import com.sims.model.Product;
import com.sims.repository.AiInsightRepository;
import com.sims.repository.BillOfMaterialItemRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDateTime;
import java.util.List;

@Service
@Slf4j
@RequiredArgsConstructor
public class CostPropagationListener {

    private final BillOfMaterialItemRepository bomRepository;
    private final AiInsightRepository aiInsightRepository;

    @Async
    @EventListener
    public void handlePriceChange(PriceChangeEvent event) {
        Product rawMaterial = event.getRawMaterial();
        BigDecimal oldPrice = event.getOldPrice();
        BigDecimal newPrice = event.getNewPrice();

        if (rawMaterial == null || oldPrice == null || newPrice == null) return;

        log.info("Async Cost Propagation: Ingredient '{}' changed from ${} to ${}", rawMaterial.getName(), oldPrice, newPrice);

        // Find all finished goods that depend on this raw material
        List<BillOfMaterialItem> impactedBoms = bomRepository.findByRawMaterial(rawMaterial);

        BigDecimal priceDelta = newPrice.subtract(oldPrice);
        BigDecimal percentChange = priceDelta
                .divide(oldPrice.compareTo(BigDecimal.ZERO) != 0 ? oldPrice : BigDecimal.ONE, 4, RoundingMode.HALF_UP)
                .multiply(BigDecimal.valueOf(100));

        for (BillOfMaterialItem bom : impactedBoms) {
            Product finishedGood = bom.getFinishedGood();
            if (finishedGood == null) continue;

            BigDecimal portionQty = bom.getQuantityRequired() != null ? bom.getQuantityRequired() : BigDecimal.ONE;
            BigDecimal bulkPackSize = rawMaterial.getPackSize() != null && rawMaterial.getPackSize().compareTo(BigDecimal.ZERO) > 0
                    ? rawMaterial.getPackSize() : BigDecimal.ONE;

            // Ingredient cost increase per finished good portion
            BigDecimal portionCostIncrease = priceDelta.divide(bulkPackSize, 6, RoundingMode.HALF_UP).multiply(portionQty);

            // Menu price
            BigDecimal retailPrice = finishedGood.getPrice() != null && finishedGood.getPrice().compareTo(BigDecimal.ZERO) > 0
                    ? finishedGood.getPrice() : BigDecimal.valueOf(10.00);

            // Gross margin erosion percentage
            BigDecimal marginErosionPct = portionCostIncrease
                    .divide(retailPrice, 4, RoundingMode.HALF_UP)
                    .multiply(BigDecimal.valueOf(100));

            String insightText = String.format(
                    "Price Deviation Alert: Supplier price for '%s' jumped by +%.1f%% ($%s -> $%s). " +
                    "Recipe cost on menu item '%s' increased by +$%.3f per plate (Margin eroded by -%.2f%%). " +
                    "Action: Review recipe portioning or adjust menu price ($%s) to protect profitability.",
                    rawMaterial.getName(), percentChange, oldPrice, newPrice,
                    finishedGood.getName(), portionCostIncrease, marginErosionPct, retailPrice
            );

            AiInsight insight = new AiInsight();
            insight.setInsight(insightText);
            insight.setType("PRICE_DEVIATION_ALERT");
            insight.setCreatedAt(LocalDateTime.now());
            aiInsightRepository.save(insight);

            log.info("Generated Price Deviation & Margin Erosion Insight: {}", insightText);
        }
    }
}

