        flagged: extractedData.filter(d => d.status === 'flagged').length,
        avgConfidence: extractedData.length > 0
            ? Math.round(extractedData.reduce((sum, d) => sum + d.confidence, 0) / extractedData.length)
            : 0
    };

    return (
