                                                        <Typography variant="body2">
                                                            X: {extractedData.find(d => d.id === expandedRow)?.coordinates.x}, Y: {extractedData.find(d => d.id === expandedRow)?.coordinates.y}
                                                        </Typography>
                                                    </Grid>
                                                    <Grid item xs={12} md={6}>
                                                        <Typography variant="subtitle2" color="text.secondary" gutterBottom>Page</Typography>
                                                        <Typography variant="body2">{extractedData.find(d => d.id === expandedRow)?.page}</Typography>
                                                    </Grid>
                                                    <Grid item xs={12}>
                                                        <Typography variant="subtitle2" color="text.secondary" gutterBottom>Original Text</Typography>
                                                        <Typography variant="body2" fontFamily="monospace" sx={{ bgcolor: 'grey.100', p: 1, borderRadius: 1, display: 'block' }}>
                                                            {extractedData.find(d => d.id === expandedRow)?.originalText}
                                                        </Typography>
                                                    </Grid>
                                                </Grid>
                                            </Box>
                                        </TableCell>
                                    </TableRow>
                                </Collapse>
                            )}

                            <TablePagination
                                rowsPerPageOptions={[5, 10, 25, 50]}
                                component="div"
                                count={filteredData.length}
                                rowsPerPage={rowsPerPage}
                                page={page}
                                onPageChange={(_, newPage) => setPage(newPage)}
                                onRowsPerPageChange={(e) => {
                                    setRowsPerPage(parseInt(e.target.value, 10));
                                    setPage(0);
                                }}
                            />
                        </Paper>

                        {/* Action Buttons */}
                        <Box sx={{ mt: 3, display: 'flex', gap: 2, justifyContent: 'flex-end', flexWrap: 'wrap' }}>
                            <Button
                                variant="outlined"
                                startIcon={<Download />}
                                onClick={handleExport}
                            >
                                Export to CSV
                            </Button>
                            <Button
                                variant="contained"
                                color="success"
                                startIcon={<CheckCircle />}
                                onClick={handleApproveAll}
                                disabled={stats.review === 0 && stats.flagged === 0}
                            >
                                Approve & Submit to ERP
                            </Button>
                        </Box>
                    </Box>
                )}

                {/* Empty State */}
                {!showExtractedData && files.length === 0 && !processing && (
                    <Paper sx={{ p: 6, mt: 4, textAlign: 'center', borderRadius: 3 }}>
                        <ReceiptLong sx={{ fontSize: 80, color: 'primary.main', mb: 2, opacity: 0.5 }} />
                        <Typography variant="h6" fontWeight={600} sx={{ mb: 1 }}>
                            Ready to Process Invoices
                        </Typography>
                        <Typography variant="body1" color="text.secondary" sx={{ mb: 3, maxWidth: 500, mx: 'auto' }}>
                            Upload your supplier invoices and let our AI extract key fields including vendor details,
                            line items, amounts, dates, and payment terms. Review and approve before syncing to your ERP.
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 2, justifyContent: 'center', flexWrap: 'wrap' }}>
                            <Chip label="PDF Support" icon={<ReceiptLong fontSize="small" />} variant="outlined" />
                            <Chip label="OCR + AI Extraction" icon={<AutoAwesome fontSize="small" />} variant="outlined" />
                            <Chip label="Confidence Scoring" icon={<TableChart fontSize="small" />} variant="outlined" />
                            <Chip label="ERP Integration Ready" icon={<CloudUpload fontSize="small" />} variant="outlined" />
                        </Box>
                    </Paper>
                )}

                {/* Snackbar */}
                <Snackbar
                    open={snackbar.open}
                    autoHideDuration={4000}
                    onClose={(e, reason) => reason !== 'clickaway' && setSnackbar({ ...snackbar, open: false })}
                >
                    <Alert
                        severity={snackbar.severity}
                        onClose={() => setSnackbar({ ...snackbar, open: false })}
                        sx={{ width: '100%' }}
                    >
                        {snackbar.message}
                    </Alert>
                </Snackbar>
            </Box>
        </Box>
    );
